import "../Styles/StudentLogin.css";
import {
  Button,
  Col,
  Container,
  Row,
  FormGroup,
  Input,
  Form,
  Label,
} from "reactstrap";
import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";

const StudentLogin = () => {
  const navigate = useNavigate();

  // states for form inputs
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  // handle login
  const handleLogin = (e) => {
    e.preventDefault();

    // استرجاع بيانات المستخدم من localStorage
    const storedData = localStorage.getItem("userData");

    if (!storedData) {
      alert("❌ No registered account found. Please sign up first.");
      return;
    }

    const user = JSON.parse(storedData);

    // تحقق من تطابق الإيميل والباسوورد
    if (email === user.email && password === user.password) {
      alert(`✅ Welcome back, ${user.name || user.companyName || "User"}!`);
      navigate("/home");
    } else {
      alert("❌ Incorrect email or password. Please try again.");
    }
  };

  return (
    <Container fluid className="login-container">
      <div className="login-box">
        <h2>
          Welcome <span>Back</span>
        </h2>
        <p className="login-subtext">Please enter your email and password</p>

        <Form onSubmit={handleLogin}>
          <Row>
            <Col md={12}>
              <FormGroup>
                <Label for="email">Email</Label>
                <Input
                  id="email"
                  name="email"
                  placeholder="Enter your Email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                />
              </FormGroup>
            </Col>
          </Row>

          <Row>
            <Col md={12}>
              <FormGroup>
                <Label for="password">Password</Label>
                <Input
                  id="password"
                  name="password"
                  placeholder="Enter your Password"
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                />
              </FormGroup>
            </Col>
          </Row>

          <Row>
            <Col md={12}>
              <Button className="login-btn" type="submit">
                Login
              </Button>
            </Col>
          </Row>

          <Row>
            <Col md={12}>
              <p className="smalltext">
                No Account? <Link to="/register">Sign up now</Link>
              </p>
            </Col>
          </Row>
        </Form>
      </div>
    </Container>
  );
};

export default StudentLogin;
